const positionKeywords = ['CEO', 'Manager', 'Director', 'Owner', 'President', 'Engineer', 'Founder', 'VP', 'Head', 'Lead'];
const domainKeywords = ['AI', 'Full Stack', 'Software', 'Marketing', 'Data Science', 'Operations', 'Product Management', 'Sales', 'Finance', 'HR'];

