};

// Helper function to pick a random element from an array
function getRandomElement(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// Helper function to ensure unique selections
function getUniqueElements(arr, count, exclude = []) {
  const available = arr.filter(item => !exclude.includes(item));
  const result = [];
  for (let i = 0; i < Math.min(count, available.length); i++) {
    const randomIndex = Math.floor(Math.random() * available.length);
    result.push(available.splice(randomIndex, 1)[0]);
  }
  return result;
}

// Function to create position variations using generic prefixes/suffixes
function createPositionVariation(basePosition) {
  const rand = Math.random();

  if (rand < 0.3) {
    // Add prefix (30% chance)
    return `${getRandomElement(positionPrefixes)} ${basePosition}`;
  } else if (rand < 0.5) {
    // Add suffix (20% chance)
    return `${basePosition} ${getRandomElement(positionSuffixes)}`;
  } else if (rand < 0.7) {
    // Add quotes (20% chance)
    return `"${basePosition}"`;
  } else {
    // Keep original (30% chance)
    return basePosition;
  }
}

// Function to create domain variations using generic prefixes/suffixes
function createDomainVariation(baseDomain) {
  const rand = Math.random();

  if (rand < 0.3) {
    // Add prefix (30% chance)
    return `${getRandomElement(domainPrefixes)} ${baseDomain}`;
  } else if (rand < 0.5) {
    // Add suffix (20% chance)
    return `${baseDomain} ${getRandomElement(domainSuffixes)}`;
  } else if (rand < 0.7) {
    // Add quotes (20% chance)
    return `"${baseDomain}"`;
  } else {
    // Keep original (30% chance)
    return baseDomain;
  }
}

// Function to create location variations
function createLocationVariation(baseLocation) {
  const locationKey = baseLocation.toLowerCase();
  const variations = locationVariations[locationKey] || [baseLocation];
  const selectedLocation = getRandomElement(variations);

  // 30% chance to add quotes around location
  return Math.random() < 0.3 ? `"${selectedLocation}"` : selectedLocation;
}

// Function to get country code for location
function getLocationCode(location) {
  const locationKey = location.toLowerCase();
  return locationCodes[locationKey] || 'unknown';
}

// Function to format DNC (Do Not Contact) domains for Google search exclusion
function formatDNC(dncInput) {
  if (!dncInput || dncInput.trim() === '') {
    return '';
  }

  console.log('Original DNC input:', dncInput); // Debug log

  // Split by semicolon, trim whitespace, and add '-' prefix to each domain
  const formatted = dncInput.split(';')
    .map(domain => domain.trim())
    .filter(domain => domain !== '') // Remove empty strings
    .map(domain => `-${domain}`)
    .join(' ');

  console.log('Formatted DNC output:', formatted); // Debug log
  return formatted;
}

