  let position, domain, location;

  if (i === 0) {
    // First result: Always use exact user input (no modifications)
    position = positionInput || getRandomElement(positionKeywords);
    domain = domainInput || getRandomElement(domainKeywords);
    location = locationInput;

    // Add to used lists if they were generated randomly
    if (!positionInput) usedPositions.push(position);
    if (!domainInput) usedDomains.push(domain);

  } else if (allFieldsFilled) {
