    position = createPositionVariation(positionInput);
    domain = createDomainVariation(domainInput);
    location = createLocationVariation(locationInput);

    // Ensure we don't create the exact same combination
    const combination = `${position}-${domain}-${location}`;
    let attempts = 0;
    while (usedCombinations.has(combination) && attempts < 5) {
      position = createPositionVariation(positionInput);
      domain = createDomainVariation(domainInput);
      location = createLocationVariation(locationInput);
      attempts++;
    }
    usedCombinations.add(combination);

  } else {
    // Some fields are empty - use random selection with uniqueness
    position = positionInput || getRandomElement(positionKeywords.filter(p => !usedPositions.includes(p)));
    domain = domainInput || getRandomElement(domainKeywords.filter(d => !usedDomains.includes(d)));
    location = locationInput;

    // Apply variations even when using defaults (but not for first result)
    if (!positionInput && position) {
      position = Math.random() < 0.4 ? createPositionVariation(position) : position;
      usedPositions.push(position);
    }
    if (!domainInput && domain) {
      domain = Math.random() < 0.4 ? createDomainVariation(domain) : domain;
      usedDomains.push(domain);
    }
    if (location) {
      location = createLocationVariation(location);
    }
  }

  outputs.push({
    Position: position,
    Location: location,
    Domaine: domain,
    DNC: formattedDNC, // Use formatted DNC with '-' prefixes
    CountryCode: getLocationCode(locationInput), // Add country code based on original input
    // Add a unique identifier for debugging
    queryVariant: i + 1
  });
}

// Return the 10 outputs
